                }

                _capture.Deliver(_capture.Silence(50), 1600);
                _capture.Deliver(_capture.Silence(50), 1600);
            }
            else
            {
                _playback.HoldBytes = false;   // the third reply is not interruptible; let it drain
            }
        };
        _vad.SpeakingFromBuffer = 0;   // the follow-ups hear silence
        _capture.OnStart = async (c, ct) =>
