    /// <summary>
    /// The toolbar's disk and officer follow their switches at each draw (2026-09-22, the user's
    /// ask): the disk after the balloon while Memory is on, its pair /memory — the pane, Enter
    /// prunes; the officer last while Shell police is on, its pair /police — the row's
    /// on/off page, ESC closing it, the draft kept (nothing until later on 2026-09-22). Memory flipped off on the General tab: the disk
    /// stays where it is, on its slab (later on 2026-10-03, the user's ask; gone until then), its pair still /memory, the lock still
    /// behind it; the police flipped off on the Tools ›
    /// Shell tab: the officer gone the same way, the ninja in its place (2026-10-02, the user's ask), whose pair is the same page.
    /// </summary>
    [Fact]
    public async Task TheToolbarDisk_AndTheOfficer_FollowMemory_AndShellPolice_AndTheOfficersPairIsThePolicePage()
    {
        _settings.Update(d => { d.TtsOutput = false; d.ToolbarItems = [.. ToolbarItems.Names]; });   // Memory, ask and the police: the defaults
        _console.Profile.Height = 40;
        _console.Profile.Width = 240;
        _geometry = new ScreenGeometry(() => null, () => 100);
        _memory.Add("Their name is Chris.");
        StepsWhenIdle(
            input => { input.PushClick(27, 103); input.PushClick(27, 103); },    // 💾: the Memory pane (at 27 right after the Usage chart since 2026-10-03, 🧮 ahead of it since 2026-10-04)
            Key(Keys.Escape),
            input =>
            {
                input.Push(Keys.Char('h'), Keys.Char('i'));
                input.PushClick(33, 103);                                        // 👮: the police page (later on 2026-09-22)
                input.PushClick(33, 103);
            },
            Key(Keys.Escape),                                                    // closed, unchanged: the draft back
            input => input.Push(Keys.Char('!'), Keys.Enter),
            Line("/settings"),
            input => input.Push(Keys.Down, Keys.Down, Keys.Down, Keys.Enter, Keys.Down, Keys.Down, Keys.Enter, Keys.Escape),   // General's fourth row, Memory mode (since 2026-10-01): its page on read-write, disabled picked; the pane closed: the disk on its slab
            input => { input.PushClick(30, 103); input.PushClick(30, 103); },    // 🔒 still at 30: the list
            Key(Keys.Escape),
            Line("/tools"),
            input => input.Push(Keys.Right, Keys.Right, Keys.Right, Keys.Down, Keys.Down, Keys.Enter, Keys.Down, Keys.Enter, Keys.Char('y'), Keys.Enter, Keys.Escape),   // the Shell tab's third row, Shell police: its page on "on", off picked and confirmed (2026-10-02); the pane closed: the officer gone
            input => { input.PushClick(33, 103); input.PushClick(33, 103); },    // 🥷 now (2026-10-02): the police page again
            Key(Keys.Escape),
            Line("/exit"));

        string output = await RunAsync();

        string cwd = WorkingDirectory.Resolve("", _settings.ProfileDirectory);
        Assert.Contains("\n" + ScreenPane.ToolbarRow(ChatScreen.ToolbarStripFor(CommandPolicyMode.Ask, true), cwd, 239), output);   // the disk there with Memory on and off alike
        Assert.Contains("\n" + ScreenPane.ToolbarRow(ChatScreen.ToolbarStripFor(CommandPolicyMode.Ask, false), cwd, 239), output);
        Assert.Equal("disabled", _settings.Current.MemoryMode);
        Assert.False(_settings.Current.ShellPolice);
        string memory = "\n" + Titled(MemoryPaneTitle(MemoryAccess.ReadWrite)) + "\n";
        string settings = "\n" + Titled(SettingsMenu.Title + " │ General · LLM · Embedded · Docker · Anthropic · OpenAI · TTS · STT · Sessions · Botchat ") + "\n";
        string tools = "\n" + Titled(ToolsText.Label + " │ Offered · Ask · Web · Shell · Files · UNC · Print · Camera · Screen · Obsidian · SQL · MySQL · SQLite · Postgres · Oracle · ClaudeCLI · Docker · HA · ComfyUI · YouTube · GitLib · Options ") + "\n";
        string allowed = "\n" + Titled(AllowedCommandsTitle) + "\n";
        Assert.Equal(1, output.Split(memory).Length - 1);
        Assert.Equal(1, output.Split(allowed).Length - 1);
        string police = "\n" + Titled(PoliceTitle) + "\n";
        Assert.True(output.IndexOf(memory, StringComparison.Ordinal) < output.IndexOf(police, StringComparison.Ordinal), output);
        Assert.True(output.IndexOf(police, StringComparison.Ordinal) < output.IndexOf("› hi!", StringComparison.Ordinal), output);   // the officer's pair: its page, then the message
        Assert.True(output.IndexOf("› hi!", StringComparison.Ordinal) < output.IndexOf(settings, StringComparison.Ordinal), output);
        Assert.True(output.IndexOf(settings, StringComparison.Ordinal) < output.IndexOf(allowed, StringComparison.Ordinal), output);
        Assert.True(output.IndexOf(allowed, StringComparison.Ordinal) < output.IndexOf(tools, StringComparison.Ordinal), output);
        Assert.True(output.IndexOf(tools, StringComparison.Ordinal) < output.LastIndexOf(police, StringComparison.Ordinal), output);
        Assert.DoesNotContain(ChatScreen.PoliceToolGlyph, output[output.LastIndexOf(police, StringComparison.Ordinal)..]);   // the row under the last pane and after it: no officer
        Assert.Contains(ChatScreen.NinjaToolGlyph, output[output.LastIndexOf(police, StringComparison.Ordinal)..]);           // the ninja instead
        string ninjaRow = "\n" + ScreenPane.ToolbarRow(ChatScreen.ToolbarStripFor(CommandPolicyMode.Ask, false), cwd, 239);
        Assert.True(output.IndexOf(ninjaRow, StringComparison.Ordinal) < output.LastIndexOf(police, StringComparison.Ordinal), output);   // the ninja's pair: the page again
        Assert.True(output.LastIndexOf(settings, StringComparison.Ordinal) < output.LastIndexOf(police, StringComparison.Ordinal), output);   // the click no longer lands on the blanks (/settings until 2026-10-02)
        Assert.All(new[] { "/memory", "/cmdlist", "/police" }, word => Assert.DoesNotContain("› " + word, output));
        Assert.Equal(ToolbarItems.Names, _settings.Current.ToolbarItems);   // untouched: every item, as the test set it
        Assert.Equal("hi!", Assert.Single(_chat.Requests).Last(m => m.Role == ChatRole.User).Text);
    }

