    [Fact]
    public async Task WithGeometry_ThinkingFunVerbs_PutsAFreshVerbOnEveryStage_TheToolStillNamed()
    {
        _settings.Update(d => { d.TtsOutput = false; d.LlmUseFunVerbs = true; });
