    /// <summary>The toolbar's glyphs, in the user's order, name their commands (2026-09-21): the six pane words (the sessions' later that day) and the chart's /usage (2026-09-29, the seventh), then the disk while Memory is on (2026-09-22) /memory, the lock Shell command policy turns — closed under ask, open under yolo, none under off (later still on 2026-09-21), either /cmdlist — and the officer while Shell police is on (2026-09-22), /police; nothing for anything else (the path's line is /cwd browse); every glyph two cells, whole under the pane's walk at either cell, the columns after the chart moving with the disk.</summary>
    [Fact]
    public void ToolbarWord_IsPinned()
    {
        // The masks since later on 2026-09-21 (the detective before); the sessions' balloon later still that day; the chart
        // 2026-09-29; the ID card and the rising chart later that day; the tool switches, the log and the viewers in the user's
        // order, the rising chart behind the log, 2026-10-03, and behind the viewers later that day.
        const string Panes = "⚙️ 🪪 🧮 🛠️ 🔌 🎓 🎭 💬 📊";   // 🧮 Themes 2026-10-04
        const string Rest = "🐚 📁 🌐 ✴️ 🐳 💎 🛢️ 🔮 🐬 🪶 🐘 🔗 🏠 🎨 📸 🖨️ 📄 ⚡ 📺 🎞️ 🪟 📈";   // 🛢️ SQL (🪟 until then) and 🪟 the Comfy thumb viewer, 2026-10-04
        Assert.Equal(Panes + " 💾 " + Rest, ChatScreen.ToolbarStrip);   // the disk always drawn since later on 2026-10-03 (the user's ask)
        Assert.Equal(Panes + " 💾 " + Rest, ChatScreen.ToolbarStripFor(CommandPolicyMode.Off, false));
        Assert.Equal(Panes + " 💾 🔒 🥷 " + Rest, ChatScreen.ToolbarStripFor(CommandPolicyMode.Ask, false));   // the ninja while the police is off (2026-10-02, the user's ask)
        Assert.Equal(Panes + " 💾 🔓 🥷 " + Rest, ChatScreen.ToolbarStripFor(CommandPolicyMode.Yolo, false));
        Assert.Equal(Panes + " 💾 " + Rest, ChatScreen.ToolbarStripFor(CommandPolicyMode.Off, true));   // no officer while the shell is off (later on 2026-09-22, the user's ask)
        Assert.Equal(Panes + " 💾 🔒 👮 " + Rest, ChatScreen.ToolbarStripFor(CommandPolicyMode.Ask, true));   // the defaults
        Assert.Equal(Panes + " 💾 🔓 👮 " + Rest, ChatScreen.ToolbarStripFor(CommandPolicyMode.Yolo, true));
        Assert.Equal("📊", ChatScreen.UsageToolGlyph);
        Assert.Equal("💾", ChatScreen.MemoryToolGlyph);
        Assert.Equal("🔒", ChatScreen.CmdAskToolGlyph);
        Assert.Equal("🔓", ChatScreen.CmdYoloToolGlyph);
        Assert.Equal("👮", ChatScreen.PoliceToolGlyph);
        Assert.Equal("🥷", ChatScreen.NinjaToolGlyph);
        Assert.Equal("  " + ChatScreen.PoliceToolGlyph + " ", TranscriptRenderer.PoliceGlyph);   // the officer the refusal line wears
        Assert.Equal("/usage", ChatScreen.ToolbarWord(ChatScreen.UsageToolGlyph));
        // The ID card and the rising chart (later on 2026-09-29, the user's ask): the profile picker, the performance bar.
        Assert.Equal("🪪", ChatScreen.ProfileToolGlyph);
        Assert.Equal("📈", ChatScreen.PerfToolGlyph);
        Assert.Equal("/profile", ChatScreen.ToolbarWord(ChatScreen.ProfileToolGlyph));
        Assert.Equal("/perfbar", ChatScreen.ToolbarWord(ChatScreen.PerfToolGlyph));
        Assert.Equal(ChatScreen.ProfileToolGlyph + " Profile", SettingsMenu.ProfileTitle);   // the picker wears the toolbar's glyph
        Assert.Equal(ChatScreen.ProfileToolGlyph + " ", NoticeGlyphs.Profile);
        Assert.Equal(ChatScreen.UsageToolGlyph + " Usage", UsageText.Label);   // the pane wears the toolbar's glyph
        Assert.Equal("/memory", ChatScreen.ToolbarWord(ChatScreen.MemoryToolGlyph));
        Assert.Equal(ChatScreen.MemoryToolGlyph + " Memory", MemoryMenu.Title);   // the pane wears the toolbar's glyph
        Assert.Equal("/cmdlist", ChatScreen.ToolbarWord(ChatScreen.CmdAskToolGlyph));
        Assert.Equal("/cmdlist", ChatScreen.ToolbarWord(ChatScreen.CmdYoloToolGlyph));
        Assert.Equal("/police", ChatScreen.ToolbarWord(ChatScreen.PoliceToolGlyph));   // later on 2026-09-22: nothing until then
        Assert.Equal("/police", ChatScreen.ToolbarWord(ChatScreen.NinjaToolGlyph));   // 2026-10-02
        Assert.Equal(McpText.Glyph, ChatScreen.McpToolGlyph);
        Assert.Equal("/cwd browse", ChatScreen.CwdBrowseLine);
        Assert.Equal("/settings", ChatScreen.ToolbarWord(ChatScreen.SettingsToolGlyph));
        Assert.Equal("/tools", ChatScreen.ToolbarWord(ChatScreen.ToolsToolGlyph));
        Assert.Equal("/mcp", ChatScreen.ToolbarWord(ChatScreen.McpToolGlyph));
        Assert.Equal("/skills", ChatScreen.ToolbarWord(ChatScreen.SkillsToolGlyph));
        Assert.Equal("/sys", ChatScreen.ToolbarWord(ChatScreen.SysToolGlyph));
        Assert.Equal("/sessions", ChatScreen.ToolbarWord(ChatScreen.SessionsToolGlyph));
        Assert.Equal(ChatScreen.SessionsToolGlyph + " Sessions", SessionsMenu.Title);   // the pane wears the toolbar's glyph
        // The tool switches and the windows (2026-10-03, the user's ask): each switch its /tools <group> page, each window its command.
        Assert.Equal("/tools shell", ChatScreen.ToolbarWord(ChatScreen.ShellToolGlyph));
        Assert.Equal("/tools files", ChatScreen.ToolbarWord(ChatScreen.FilesToolGlyph));
        Assert.Equal("/tools claude", ChatScreen.ToolbarWord(ChatScreen.ClaudeToolGlyph));
        Assert.Equal("/tools ha", ChatScreen.ToolbarWord(ChatScreen.HaToolGlyph));
        Assert.Equal("/tools print", ChatScreen.ToolbarWord(ChatScreen.PrintToolGlyph));
        Assert.Equal("/log", ChatScreen.ToolbarWord(ChatScreen.LogToolGlyph));
        Assert.Equal("/camera live", ChatScreen.ToolbarWord(ChatScreen.LiveViewToolGlyph));
        Assert.Equal("/comfy view", ChatScreen.ToolbarWord(ChatScreen.ComfyViewToolGlyph));
        // The abacus and the window (2026-10-04, the user's ask): the theme picker, which wears it, and /comfy thumbs' browser.
        Assert.Equal("🧮", ChatScreen.ThemeToolGlyph);
        Assert.Equal("/theme", ChatScreen.ToolbarWord(ChatScreen.ThemeToolGlyph));
        Assert.Equal(ChatScreen.ThemeToolGlyph + " Theme", SettingsMenu.ThemeTitle);
        Assert.Equal("🪟", ChatScreen.ComfyThumbsToolGlyph);
        Assert.Equal("/comfy thumbs", ChatScreen.ToolbarWord(ChatScreen.ComfyThumbsToolGlyph));
        Assert.Equal("🛢️", ChatScreen.SqlToolGlyph);
        // The bolt (2026-10-05, the user's ask; ⏳ for a few hours): /process's list, a pane, so no window toggle; the list pane wears it.
        Assert.Equal("⚡", ChatScreen.ProcessToolGlyph);
        Assert.Equal("/process", ChatScreen.ToolbarWord(ChatScreen.ProcessToolGlyph));
        Assert.False(ChatScreen.TogglesWindow("/process"));
        Assert.Equal(ChatScreen.ProcessToolGlyph + " Process", ProcessMenu.Title);
        Assert.Equal(NeonSidekick.Viewer.ViewerText.StripButton, ChatScreen.ComfyViewToolGlyph);   // the picture strip's button, one source
        Assert.Equal(NeonSidekick.Docker.DockerText.Glyph, ChatScreen.DockerToolGlyph);
        Assert.All(ToolsText.SwitchWords, word => Assert.Equal(ToolsText.SwitchLine(word), ChatScreen.ToolbarWord(ToolbarItems.Glyph(word))));
        Assert.True(ChatScreen.TogglesWindow("/log") && ChatScreen.TogglesWindow("/camera live") && ChatScreen.TogglesWindow("/comfy view") && ChatScreen.TogglesWindow("/comfy thumbs"));
        Assert.False(ChatScreen.TogglesWindow("/tools web") || ChatScreen.TogglesWindow("/log --file") || ChatScreen.TogglesWindow(null));
        Assert.Null(ChatScreen.ToolbarWord("📂"));
        Assert.Null(ChatScreen.ToolbarWord(ChatScreen.TtsGlyph));
        Assert.Null(ChatScreen.ToolbarWord(""));
        string[] glyphs = ChatScreen.ToolbarStrip.Split(' ');
        Assert.Equal(32, glyphs.Length);   // 🪶 SQLite and 🐘 PostgreSQL since 2026-10-04, 🧮 and 🪟 later that day, ⚡ 2026-10-05
        for (int i = 0; i < glyphs.Length; i++)
        {
            Assert.Equal(2, TextCells.Width(glyphs[i]));
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, glyphs[i], 3 * i), ScreenPane.ToolbarHitAt(ChatScreen.ToolbarStrip, -1, 0, 3 * i));
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, glyphs[i], 3 * i), ScreenPane.ToolbarHitAt(ChatScreen.ToolbarStrip, -1, 0, 3 * i + 1));
        }

        Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(ChatScreen.ToolbarStrip, -1, 0, 23).Zone);   // the separator ahead of the ninth
        Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(ChatScreen.ToolbarStrip, -1, 0, 26).Zone);   // the one after it
        Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(ChatScreen.ToolbarStrip, -1, 0, 3 * glyphs.Length).Zone);   // past the last
        Assert.Equal(2, TextCells.Width(ChatScreen.MemoryToolGlyph));
        Assert.Equal(2, TextCells.Width(ChatScreen.PoliceToolGlyph));
        Assert.Equal(2, TextCells.Width(ChatScreen.NinjaToolGlyph));
        foreach (var (policy, padlock) in new[] { (CommandPolicyMode.Ask, ChatScreen.CmdAskToolGlyph), (CommandPolicyMode.Yolo, ChatScreen.CmdYoloToolGlyph) })
        {
            Assert.Equal(2, TextCells.Width(padlock));
            string strip = ChatScreen.ToolbarStripFor(policy, false);   // the disk at 27 whatever Memory is (later on 2026-10-03; 24 until 🧮, 2026-10-04), the lock at 30
            Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(strip, -1, 0, 29).Zone);   // the separator ahead of the lock
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, padlock, 30), ScreenPane.ToolbarHitAt(strip, -1, 0, 30));
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, padlock, 30), ScreenPane.ToolbarHitAt(strip, -1, 0, 31));
            Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(strip, -1, 0, 32).Zone);   // past it
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.NinjaToolGlyph, 33), ScreenPane.ToolbarHitAt(strip, -1, 0, 34));   // the ninja after it (2026-10-02)
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.ShellToolGlyph, 36), ScreenPane.ToolbarHitAt(strip, -1, 0, 36));   // the shell after that (2026-10-03)

            string full = ChatScreen.ToolbarStripFor(policy, true);   // the disk, then the lock at 30, the officer after at 33 (the disk right after the Usage chart since 2026-10-03)
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.MemoryToolGlyph, 27), ScreenPane.ToolbarHitAt(full, -1, 0, 27));
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.MemoryToolGlyph, 27), ScreenPane.ToolbarHitAt(full, -1, 0, 28));
            Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(full, -1, 0, 29).Zone);
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, padlock, 30), ScreenPane.ToolbarHitAt(full, -1, 0, 30));
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, padlock, 30), ScreenPane.ToolbarHitAt(full, -1, 0, 31));
            Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(full, -1, 0, 32).Zone);
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.PoliceToolGlyph, 33), ScreenPane.ToolbarHitAt(full, -1, 0, 33));
            Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.PoliceToolGlyph, 33), ScreenPane.ToolbarHitAt(full, -1, 0, 34));
            Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(full, -1, 0, 35).Zone);   // past it

        }

        string noLock = ChatScreen.ToolbarStripFor(CommandPolicyMode.Off, true);   // policy off: neither the lock nor the officer (later on 2026-09-22), the shell after the disk
        Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.MemoryToolGlyph, 27), ScreenPane.ToolbarHitAt(noLock, -1, 0, 27));
        Assert.Equal(ScreenPane.ToolbarZone.Row, ScreenPane.ToolbarHitAt(noLock, -1, 0, 29).Zone);
        Assert.Equal(new ScreenPane.ToolbarHit(ScreenPane.ToolbarZone.Glyph, ChatScreen.ShellToolGlyph, 30), ScreenPane.ToolbarHitAt(noLock, -1, 0, 30));
    }

    /// <summary>A double-click on the scroll's hint at the idle line (later on 2026-09-18) is Ctrl+End — the bottom again, the draft kept, no settings pane.</summary>
    [Fact]
    public async Task ADoubleClickOnTheScrolledHint_AtIdle_IsTheBottomAgain_AndOpensNothing()
    {
        _settings.Update(d => { d.TtsOutput = false; d.TranscriptMarkdown = false; });
        _console.Profile.Height = 10;
        _geometry = new ScreenGeometry(() => null, () => 100);   // the scroll's row at 98, over the upper rule (2026-10-01; the hint row's 102 until then)
        string rows = string.Concat(Enumerable.Range(1, 12).Select(i => "row" + i + "\n"));
        _chat.EnqueueText(rows);
        _chat.EnqueueText("ok");
        StepsWhenIdle(
            Line("hi"),
            input =>
            {
                input.Push(Keys.PageUp);
                input.PushClick(20, 98);
                input.PushClick(20, 98);
                input.Push(Keys.Char('!'));
                input.Push(Keys.Enter);
            },
            Line("/exit"));

        string output = await RunAsync();

        Assert.Contains("rows below", output);
        // The pair's redraw writes the transcript's tail back (row12) before the "!" is typed: the bottom came from the clicks, not from the Enter.
        string after = output[(output.LastIndexOf("rows below", StringComparison.Ordinal) + 1)..];
        int tail = after.IndexOf("row12", StringComparison.Ordinal);
        int draft = after.IndexOf('!');   // the typed character alone: the input row's redraw writes the changed cell
        Assert.True(tail >= 0 && draft > tail, after);
        Assert.DoesNotContain(SettingsMenu.Title + " │ General", output);
        Assert.Equal("!", _chat.Requests[1].Last(m => m.Role == ChatRole.User).Text);
    }

    /// <summary>The model name at the row's right edge (2026-09-18): a double-click there is /server (2026-09-22; /model before) — the server list, then the model list, then the reasoning list, as the typed command; Enter keeps the server, ESC the model and the level — with no › row.</summary>
    [Fact]
    public async Task ADoubleClickOnTheModelName_RunsTheServerFlow()
    {
        _settings.Update(d => { d.TtsOutput = false; d.LlmUrl = "http://127.0.0.1:1234/v1"; d.LlmModel = "llama"; });
        _console.Profile.Height = 40;
        _console.Profile.Width = 240;
        _geometry = new ScreenGeometry(() => null, () => 100);
        // "llama" and its reasoning mark end at column 238; 236 is inside the name either way.
        StepsWhenIdle(
            input =>
            {
                input.PushClick(236, 102);
                input.PushClick(236, 102);
                input.Push(Keys.Enter, Keys.Escape, Keys.Escape);   // the server in use, keep the model, keep the level
            },
            Line("/exit"));

        string output = await RunAsync();

        Assert.Contains(Titled(SettingsMenu.ServerTitle), output);
        Assert.Contains("\n" + Titled(SettingsMenu.ModelTitle) + "\n \n▸ llama\n", output);
        Assert.Contains(Titled(SettingsMenu.ReasoningTitle), output);
        Assert.Equal(2, output.Split("  · " + SettingsMenu.UnchangedNotice).Length - 1);   // one per menu kept
        Assert.Equal("llama", _settings.Current.LlmModel);
        Assert.DoesNotContain("› /server", output);
    }

