        File.WriteAllText(Path.Combine(files, "blank.txt"), " \n\t\n");
        File.WriteAllText(Path.Combine(files, "big.txt"), string.Join("\n", Enumerable.Range(0, 700).Select(i => new string('x', 50))));   // 35,700 characters: cut at 32,000
        PushLine("/speak");
