        Assert.Equal(8 * 12, Count(output[screens[3]..screens[4]], TileLine));     // /splash over tiled: page 1
        Assert.Equal(2 * 12, Count(output[screens[4]..screens[5]], TileLine));     // and the arrows page it
    }

