    {
        // 2026-09-23, the user's call: /tree follows File browser/tree mode — default leaves dot-files and dot-folders out, show-hidden lists them.
        _settings.Update(d => { d.FileTreeShowSizes = false; d.FileBrowserMode = mode; });
