    [Fact]
    public void ArgumentItems_TheLevels_TheProfiles_TheTimers_AndTheRest()
    {
        var sources = Sources(timers: ["tea", "the big pot of soup"]);

        Assert.Equal(ReasoningLevel.Levels, Texts(ChatScreen.ArgumentItems("/reasoning", "", sources)));
        Assert.Equal([new CompletionItem("high", ReasoningLevel.Describe("high"))], ChatScreen.ArgumentItems("/reasoning", "h", sources));

        // /theme (2026-09-23): the names with their notes, in menu order (A to Z since 2026-10-03), then export (2026-10-01).
        Assert.Equal([.. ThemeName.Names, ThemeText.ExportWord], Texts(ChatScreen.ArgumentItems("/theme", "", sources)));
        Assert.Equal(["nebula", "netrunner", "nixie", "noir", "nostromo"], Texts(ChatScreen.ArgumentItems("/theme", "n", sources)));   // A to Z since 2026-10-03
        Assert.Equal([new CompletionItem("netrunner", "green phosphor")], ChatScreen.ArgumentItems("/theme", "net", sources));
        Assert.Equal(PerfBarMode.Words, Texts(ChatScreen.ArgumentItems("/perfbar", "", sources)));
        // The commands whose argument is a path of their own keep their list over a mention (2026-09-30).
        Assert.True(ChatScreen.TakesPathArgument("/speak") && ChatScreen.TakesPathArgument("/view") && ChatScreen.TakesPathArgument("/PRINT"));
        Assert.True(ChatScreen.TakesPathArgument("/tree") && ChatScreen.TakesPathArgument("/explore") && ChatScreen.TakesPathArgument("/vault") && ChatScreen.TakesPathArgument("/terminal"));   // their folder lists
        Assert.False(ChatScreen.TakesPathArgument("/loop") || ChatScreen.TakesPathArgument("/plan") || ChatScreen.TakesPathArgument("/claude"));   // off and the looks (later on 2026-09-29)
        Assert.True(ChatScreen.TakesPathArgument("/cwd"));   // any drive's folders (2026-10-05)
        Assert.Equal([new CompletionItem("gauge", PerfBarMode.Describe("gauge"))], ChatScreen.ArgumentItems("/perfbar", "g", sources));

        // /profile: the names (the loaded one marked) then the verbs; a verb typed opens the names behind it.
        Assert.Equal(["chef", "default", "work", "add", "delete", "edit", "pull", "push", "reload", "rename", "reset"], Texts(ChatScreen.ArgumentItems("/profile", "", sources)));   // edit and reload 2026-09-21, pull and push 2026-09-28
        Assert.Equal(ChatScreen.LoadedProfileNote, ChatScreen.ArgumentItems("/profile", "", sources)[1].Note);
        Assert.Equal(ChatScreen.SwitchToProfileNote, ChatScreen.ArgumentItems("/profile", "", sources)[2].Note);
        Assert.Equal(ChatScreen.ProfileVerbs[1], ChatScreen.ArgumentItems("/profile", "del", sources)[0]);
        Assert.Equal(["delete chef", "delete work"], Texts(ChatScreen.ArgumentItems("/profile", "delete ", sources)));   // default never (2026-09-22)
        Assert.Equal(["rename work"], Texts(ChatScreen.ArgumentItems("/profile", "rename w", sources)));
        Assert.Equal(["rename chef", "rename work"], Texts(ChatScreen.ArgumentItems("/profile", "rename ", sources)));   // default never: it can't be renamed (2026-09-22)
        Assert.Equal(["rename chef", "rename work"], Texts(ChatScreen.ArgumentItems("/profile", "rename ", Sources(loaded: "work"))));
        Assert.Empty(ChatScreen.ArgumentItems("/profile", "rename d", sources));
        Assert.Equal(["reset chef"], Texts(ChatScreen.ArgumentItems("/profile", "reset c", sources)));
        Assert.Equal(["reset --all", "reset chef", "reset default", "reset work"], Texts(ChatScreen.ArgumentItems("/profile", "reset ", sources)));   // default loaded: it may reset itself; --all first (2026-09-27)
        Assert.Equal(["reset --all", "reset chef", "reset work"], Texts(ChatScreen.ArgumentItems("/profile", "reset ", Sources(loaded: "work"))));   // but not from another profile (2026-09-22)
        Assert.Equal([new CompletionItem("reset --all", ChatScreen.ResetAllNote)], ChatScreen.ArgumentItems("/profile", "reset -", sources));
        Assert.Equal(["reset chef --all"], Texts(ChatScreen.ArgumentItems("/profile", "reset chef ", sources)));   // after a name once it is typed with its space
        Assert.Empty(ChatScreen.ArgumentItems("/profile", "reset default ", Sources(loaded: "work")));
        Assert.Equal(["delete chef", "delete work"], Texts(ChatScreen.ArgumentItems("/profile", "delete ", Sources(loaded: "work"))));   // delete never lists it (2026-09-22)
        Assert.Empty(ChatScreen.ArgumentItems("/profile", "add ", sources));          // a new name is free text
        Assert.Empty(ChatScreen.ArgumentItems("/profile", "edit ", sources));         // edit and reload take nothing
        Assert.Empty(ChatScreen.ArgumentItems("/profile", "reload ", sources));
        Assert.Empty(ChatScreen.ArgumentItems("/profile", "rename work ", sources));  // so is the new name
        // push and pull (2026-09-28): every profile but the loaded one, default included (the user's call); nothing after the name.
