    // ── A double-clicked picture opens in the image editor (later on 2026-09-24) ─

    /// <summary>A pair of clicks on every transcript row at <paramref name="column"/>: wherever the picture landed, its rows answer; the others are nothing.</summary>
    private static Action<ScriptedInput> DoubleClickDown(int column) => input =>
    {
        for (int y = 60; y < 99; y++)
        {
            input.PushClick(column, y);
            input.PushClick(column, y);
        }
    };

    [WindowsFact]
    public async Task APictureDoubleClicked_OpensInTheImageEditor_TheSettingsCommandPassed_AndNoLinePrinted()
    {
        _settings.Update(d => { d.TtsOutput = false; d.ImageEditor = "mspaint"; });
        PaneOf40Rows();
        string files = Path.Combine(_settings.ProfileDirectory, WorkingDirectory.DefaultFolderName);
        Directory.CreateDirectory(Path.Combine(files, "docs"));
        File.WriteAllBytes(Path.Combine(files, "docs", "square.bmp"), SmokeChecks.SolidBmp(4, 4));
        var opened = new List<(string Path, string Editor)>();
        _openImage = (path, editor) => opened.Add((path, editor));
        StepsWhenIdle(Line("/view --chat docs/square.bmp"), DoubleClickDown(119), DoubleClickDown(10), Line("/exit"));

        string output = await RunAsync();

        // Every picture row of the downward pass opens it; the column-10 pass hits nothing. A good open prints no line (2026-09-24).
        Assert.NotEmpty(opened);
        Assert.All(opened, o => Assert.Equal((Path.Combine(files, "docs", "square.bmp"), "mspaint"), o));
        Assert.DoesNotContain("🖼️ opened", output);
        Assert.Empty(_chat.Requests);
    }

    /// <summary>
    /// The built-in viewer takes a double-clicked picture (later on 2026-09-27, the user's call): with the <c>Image viewer</c>
    /// setting empty and a viewer to open, the picture's full path goes to it and the registered app is not started;
    /// <c>system</c> sends it to the registered app (the old empty); a viewer that will not start falls back to that app.
    /// </summary>
    [WindowsTheory]
    [InlineData("", false, true)]
    [InlineData("System", false, false)]
    [InlineData("", true, false)]
    public async Task APictureDoubleClicked_OpensInTheBuiltInViewer_UnlessSystem_OrTheViewerFails(string setting, bool viewerFails, bool expectViewer)
    {
        _settings.Update(d => { d.TtsOutput = false; d.ImageEditor = setting; });
        PaneOf40Rows();
        string files = Path.Combine(_settings.ProfileDirectory, WorkingDirectory.DefaultFolderName);
        Directory.CreateDirectory(Path.Combine(files, "docs"));
        string picture = Path.Combine(files, "docs", "square.bmp");
        File.WriteAllBytes(picture, SmokeChecks.SolidBmp(4, 4));
        var viewed = new List<string>();
        var opened = new List<(string Path, string Editor)>();
        _viewPicture = path =>
        {
            viewed.Add(path);
            if (viewerFails)
            {
                throw new InvalidOperationException("no window");
            }
        };
        _openImage = (path, editor) => opened.Add((path, editor));
        StepsWhenIdle(Line("/view --chat docs/square.bmp"), DoubleClickDown(119), Line("/exit"));

        string output = await RunAsync();

        if (expectViewer)
        {
            Assert.NotEmpty(viewed);
            Assert.All(viewed, v => Assert.Equal(picture, v));
            Assert.Empty(opened);
        }
        else
        {
            Assert.NotEmpty(opened);
            Assert.All(opened, o => Assert.Equal((picture, ""), o));
            Assert.Equal(viewerFails, viewed.Count > 0);
        }

        Assert.DoesNotContain("Could not open", output);
    }

    /// <summary>
    /// A <c>/loop</c> wait keeps the mouse (2026-09-24, the user's ask: the pictures froze while a loop
    /// waited): a picture double-clicked in the wait opens, and ESC after it still ends the loop.
    /// </summary>
    [WindowsFact]
    public async Task APictureDoubleClicked_DuringALoopWait_Opens_AndEscStillEndsTheLoop()
    {
        _settings.Update(d => { d.TtsOutput = false; d.ImageEditor = "mspaint"; });
        PaneOf40Rows();
        string files = Path.Combine(_settings.ProfileDirectory, WorkingDirectory.DefaultFolderName);
        Directory.CreateDirectory(Path.Combine(files, "docs"));
        File.WriteAllBytes(Path.Combine(files, "docs", "square.bmp"), SmokeChecks.SolidBmp(4, 4));
        var opened = new System.Collections.Concurrent.ConcurrentQueue<(string Path, string Editor)>();
        _openImage = (path, editor) => opened.Enqueue((path, editor));
        _chat.EnqueueText("One.");
        _chat.EnqueueText("never");
        var input = Scripted();
        StepsWhenIdle(Line("/view --chat docs/square.bmp"), Line("/loop 2 1m hi"), Line("/exit"));
        using var done = new CancellationTokenSource();
        var clicks = Task.Run(async () =>
        {
            await WaitUntilAsync(() => done.IsCancellationRequested || Output.Contains(ChatScreen.LoopWaitNotice(TimeSpan.FromMinutes(1)), StringComparison.Ordinal));
            DoubleClickDown(119)(input);
            await WaitUntilAsync(() => done.IsCancellationRequested || !opened.IsEmpty);
            input.Push(Keys.Escape);
        });

        string output = await RunAsync();
        await done.CancelAsync();
        await clicks;

        Assert.NotEmpty(opened);
        Assert.All(opened, o => Assert.Equal((Path.Combine(files, "docs", "square.bmp"), "mspaint"), o));
        Assert.Single(_chat.Requests);
        Assert.Contains(ChatScreen.LoopStoppedNotice(1), output);
        Assert.DoesNotContain(ChatScreen.LoopTurnNotice(2, 2), output);
    }

    [WindowsFact]
    public async Task APictureWithNoFile_IsWrittenToTemp_AndAGoneFileIsAnError()
    {
        _settings.Update(d => { d.TtsOutput = false; d.WelcomeSplashMode = "disabled"; });
        PaneOf40Rows();
        SplashOf((4, 4));
        string files = Path.Combine(_settings.ProfileDirectory, WorkingDirectory.DefaultFolderName);
        Directory.CreateDirectory(files);
        File.WriteAllBytes(Path.Combine(files, "gone.bmp"), SmokeChecks.SolidBmp(4, 4));
        StepsWhenIdle(
            Line("/splash"),
            DoubleClickDown(119),
            Line("/clear"),
            Line("/view --chat gone.bmp"),
            input => { File.Delete(Path.Combine(files, "gone.bmp")); DoubleClickDown(119)(input); },
            Line("/exit"));

        string output = await RunAsync();

        string temp = Path.Combine(ChatScreen.PictureTempFolder, "01.bmp");
        Assert.Contains(temp, _openedFiles);   // the bundled splash has no file: its bytes went to temp
        Assert.True(File.Exists(temp));
        Assert.Contains(ChatScreen.PictureGoneError(Path.Combine(files, "gone.bmp")), output);
        Assert.DoesNotContain(Path.Combine(files, "gone.bmp"), _openedFiles);
        Assert.DoesNotContain("🖼️ opened", output);   // a good open prints nothing, only the error above (2026-09-24)
    }

    [WindowsFact]
    public async Task ATiledSplashPictureDoubleClicked_Opens_WithNoNoticeLine()
    {
        // The splash's pictures open without the "(🖼️ opened …)" line; only an error would print (2026-09-24, the user's call).
        _settings.Update(d => { d.TtsOutput = false; d.WelcomeSplashMode = "tiled"; d.ImageThumbnailSize = "small"; });
        PaneOf40Rows();
        SplashOf((480, 240), (480, 240), (480, 240));
        StepsWhenIdle(DoubleClickDown(10), Line("/exit"));

        string output = await RunAsync();

        Assert.Contains(Path.Combine(ChatScreen.PictureTempFolder, "01.bmp"), _openedFiles);
        Assert.DoesNotContain("🖼️ opened", output);
    }

    /// <summary>The "Connect a model" page's rows (2026-10-04, the UI review): every way to a model, the embedded one only where it can run, "Not now" last.</summary>
    [Fact]
    public void ConnectRows_AreEveryWayToAModel()
    {
        Assert.Equal([ConnectChoice.Scan, ConnectChoice.Url, ConnectChoice.Embedded, ConnectChoice.Docker, ConnectChoice.Anthropic, ConnectChoice.OpenAI, ConnectChoice.ClaudeCli, ConnectChoice.NotNow], ChatScreen.ConnectRows(embedded: true).Select(r => r.Choice));
        Assert.Contains(ChatScreen.ConnectRows(embedded: false), r => r.Choice == ConnectChoice.Docker);   // after Embedded (2026-10-05), wherever it can run
        Assert.DoesNotContain(ChatScreen.ConnectRows(embedded: false), r => r.Choice == ConnectChoice.Embedded);
        Assert.Equal("Not now", ChatScreen.ConnectRows(embedded: false)[^1].Label);
        Assert.Equal("ab   " + Theme.DimMarkup("note"), ChatScreen.ConnectRow("ab", "note", 5));
        Assert.Equal("🖥️ Connect a model", ChatScreen.ConnectTitle);
        Assert.Equal("🖥️ http://x:9/v1 did not answer /v1/models; using it anyway, as it is the configured URL. " + ModelErrorText.UnreachableNextStep, ChatScreen.NotAnsweringNotice(new Uri("http://x:9/v1")));
    }

    /// <summary>
    /// One click on a toolbar glyph says what it is (2026-10-04, the UI review): its note flashed on the hint row, the state with it —
    /// the shell's policy, a tool switch on or off, a pane's name alone; the second click still opens it.
    /// </summary>
    [Fact]
    public void AToolbarGlyphsNote_NamesItsItem_AndItsState()
    {
        var shown = new AppSettingsData { ShellCommandPolicy = "ask", WebTools = false };
        Assert.Equal("🐚 Shell: ask · double-click to open", ChatScreen.ToolbarGlyphNote(ChatScreen.ShellToolGlyph, shown));
        Assert.Equal(ChatScreen.WebToolGlyph + " Web: off · " + ToolbarItems.DoubleClickNote, ChatScreen.ToolbarGlyphNote(ChatScreen.WebToolGlyph, shown));
        Assert.Equal(ChatScreen.SettingsToolGlyph + " Settings · " + ToolbarItems.DoubleClickNote, ChatScreen.ToolbarGlyphNote(ChatScreen.SettingsToolGlyph, shown));
        Assert.Equal(ChatScreen.MemoryToolGlyph + " Memory: read-write · " + ToolbarItems.DoubleClickNote, ChatScreen.ToolbarGlyphNote(ChatScreen.MemoryToolGlyph, shown));
        Assert.Equal(ToolbarItems.CmdList, ChatScreen.ToolbarItemOf(ChatScreen.CmdYoloToolGlyph));
        Assert.Equal(ToolbarItems.Police, ChatScreen.ToolbarItemOf(ChatScreen.NinjaToolGlyph));
        Assert.Null(ChatScreen.ToolbarGlyphNote("+", shown));
        Assert.All(ToolbarItems.Names.Where(id => id != ToolbarItems.Path), id => Assert.Equal(id, ChatScreen.ToolbarItemOf(ToolbarItems.Glyph(id))));
    }

